"""What each video shows and says. One dict per part; scenes play in order.

kinds: title | code (file, at=regex of first line, lines, hl=regexes to highlight) |
       term (cmd run for real in cwd) | web (port, mode, steps)
"""

V = "iframe"           # an HtmlView sandbox on the page
MV = "iframe.mcp-view"  # an MCP App view mounted by the host


def title(t, sub, bullets, caption, secs=10):
    return {"kind": "title", "title": t, "subtitle": sub, "bullets": bullets, "caption": caption, "secs": secs}


def code(file, at, caption, secs=11, lines=26, hl=()):
    return {"kind": "code", "file": file, "at": at, "caption": caption, "secs": secs, "lines": lines, "hl": list(hl)}


def term(cwd, cmd, caption, secs=14):
    return {"kind": "term", "cwd": cwd, "cmd": cmd, "caption": caption, "secs": secs}


def web(port, mode, caption, steps=(), secs=10):
    return {"kind": "web", "port": port, "mode": mode, "caption": caption,
            "steps": [("idle",)] + list(steps), "secs": secs}


